SELECT DISTINCT tr.trNumber,w.workItemCode,cr.*,sp.specNumber,sp.specRelease,s.sectionId,s.sectionTitle FROM TechnicalReport tr JOIN rel_RELATED_TO_WORK_ITEM rw ON rw.src_id=tr.node_id JOIN WorkItem study ON study.node_id=rw.dst_id JOIN WorkItem w ON w.workItemCode=substr(study.workItemCode,4)||'-Core' JOIN rel_RELATED_TO wc ON wc.dst_id=w.node_id JOIN CR cr ON cr.node_id=wc.src_id JOIN rel_MODIFIES m ON m.src_id=cr.node_id JOIN Spec sp ON sp.node_id=m.dst_id LEFT JOIN rel_MODIFIES_SECTION k ON k.src_id=cr.node_id LEFT JOIN Section s ON s.node_id=k.dst_id WHERE tr.trNumber='38.824' AND substr(study.workItemCode,1,3)='FS_' AND sp.specNumber IN ('38.211','38.214') ORDER BY sp.specNumber,cr.id,s.sectionId
